  if(module==='STP')d.push(T('Root changed: ','Root değişimi: ')+(b.root?name(b.root):'—')+' → '+(r.root?name(r.root):'—')+'. '+T('Blocked connections: ','Bloklu bağlantılar: ')+(r.blockedLinks.map(id=>{const l=links.find(x=>x.id===id);return name(l.a)+' ↔ '+name(l.b);}).join('; ')||T('none','yok'))+'.');
